    <!-- Header -->
    <header class="header">
        <div class="nav-container">
            🔍 AI Kereső
            <nav>
                <ul class="nav-links">
                    <li>Rólunk</li>
                    <li>Kapcsolat</li>
                    <li>Belépés</li>
                </ul>
            </nav>
        </div>
    </header>

    <!-- Main Chat Interface -->
    <div class="chat-container">
        <!-- Welcome Section -->
        <div class="welcome-section">
            <h1 class="welcome-title">AI Kereső</h1>
            <p class="welcome-subtitle">Tegyen fel bármilyen kérdést magyarul, és intelligensen keresi meg a választ az interneten.</p>
        </div>

        <!-- Messages Area -->
        <div class="messages-container" id="messagesContainer">
            <!-- Example messages will be inserted here -->
        </div>

        <!-- Input Area -->
        <div class="input-container">
            <div class="input-box">
                <textarea 
                    id="messageInput" 
                    class="input-field" 
                    placeholder="Írja be kérdését vagy üzenetét..." 
                    rows="1"
                    onkeydown="handleKeyDown(event)"
                    oninput="autoResize(this)"
                ></textarea>
                <button class="send-btn" id="sendBtn" onclick="sendMessage()">
                    ➤
                </button>
            </div>
        </div>
    </div>

    <!-- Pricing Toggle -->
    <div class="pricing-toggle">
        <button class="pricing-btn" onclick="showModal('pricing')">💎 Prémium</button>
    </div>

    <!-- Modal -->
    <div id="modal" class="modal">
        <div class="modal-content">
            <button class="modal-close" onclick="closeModal()">&times;</button>
            <div id="modalBody"></div>
        </div>
    </div>

    <script>
        let conversationHistory = [];
        let isProcessing = false;

        // Auto-resize textarea
        function autoResize(textarea) {
            textarea.style.height = 'auto';
            textarea.style.height = Math.min(textarea.scrollHeight, 120) + 'px';
        }

        // Handle keyboard shortcuts
        function handleKeyDown(event) {
            if (event.key === 'Enter' && !event.shiftKey) {
                event.preventDefault();
                sendMessage();
            }
        }

        // Send message function
        async function sendMessage() {
            const input = document.getElementById('messageInput');
            const sendBtn = document.getElementById('sendBtn');
            const message = input.value.trim();

            if (!message || isProcessing) return;

            isProcessing = true;
            sendBtn.disabled = true;

            // Add user message to chat
            addMessage(message, 'user');
            input.value = '';
            input.style.height = 'auto';

            // Add typing indicator
            const typingId = addTypingIndicator();

            try {
                // Optimize search query using AI
                const optimizedQuery = await optimizeSearchQuery(message);

                const response = await fetch('/api/search', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({ query: optimizedQuery })
                });

                if (!response.ok) {
                    throw new Error(`HTTP error! status: ${response.status}`);
                }

                removeTypingIndicator(typingId);

                const reader = response.body.getReader();
                const decoder = new TextDecoder();
                let aiResponse = '';
                let searchResults = [];
                let messageId = null;

                while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;

                    const chunk = decoder.decode(value);
                    const lines = chunk.split('\n');

                    for (const line of lines) {
                        if (line.startsWith('data: ')) {
                            const data = line.slice(6).trim();
                            if (data && data !== '') {
                                try {
                                    const parsed = JSON.parse(data);

                                    if (parsed.type === 'ai_chunk') {
                                        aiResponse += parsed.content;
                                        if (!messageId) {
                                            messageId = addMessage('', 'ai');
                                        }
                                        updateMessage(messageId, aiResponse);
                                    } else if (parsed.type === 'search_results') {
                                        searchResults = parsed.results;
                                    } else if (parsed.type === 'complete') {
                                        if (messageId && searchResults.length > 0) {
                                            addSourceLinks(messageId, searchResults);
                                        }
                                    } else if (parsed.type === 'error') {
                                        throw new Error(parsed.message);
                                    }
                                } catch (parseError) {
                                    console.warn('Failed to parse JSON:', data, parseError);
                                }
                            }
                        }
                    }
                }

            } catch (error) {
                removeTypingIndicator(typingId);
                console.error('Error:', error);
                addMessage('Sajnálom, hiba történt a válasz generálása során. Kérjük próbálja újra.', 'ai');
            } finally {
                isProcessing = false;
                sendBtn.disabled = false;
            }
        }

        // Optimize search query for Exa
        async function optimizeSearchQuery(userMessage) {
            // Simple optimization logic - in a real implementation, 
            // this could use a lightweight AI model or more sophisticated processing
            let optimized = userMessage;

            // Remove common Hungarian question words that don't help search
            const removeWords = ['mi', 'milyen', 'hogy', 'hogyan', 'miért', 'mikor', 'hol', 'mit', 'kinek'];
            const words = optimized.toLowerCase().split(' ');
            const filteredWords = words.filter(word => !removeWords.includes(word));

            if (filteredWords.length > 0) {
                optimized = filteredWords.join(' ');
            }

            // Add context for better search results
            if (userMessage.includes('recept') || userMessage.includes('főzés')) {
                optimized += ' recept főzés konyha';
            } else if (userMessage.includes('egészség') || userMessage.includes('betegség')) {
                optimized += ' egészség orvosi információ';
            } else if (userMessage.includes('tech') || userMessage.includes('technológia')) {
                optimized += ' technológia számítógép szoftver';
            }

            return optimized;
        }

        // Add message to chat
        function addMessage(content, type) {
            const messagesContainer = document.getElementById('messagesContainer');
            const messageId = 'msg_' + Date.now();

            const messageDiv = document.createElement('div');
            messageDiv.className = `message ${type}`;
            messageDiv.id = messageId;

            const avatar = type === 'user' ? '👤' : '🤖';
            const title = type === 'user' ? '' : '<h4>AI Válasz</h4>';

            messageDiv.innerHTML = `
                <div class="message-avatar">${avatar}</div>
                <div class="message-content">
                    ${title}
                    <div class="message-text">${content || ''}</div>
                </div>
            `;

            messagesContainer.appendChild(messageDiv);
            messagesContainer.scrollTop = messagesContainer.scrollHeight;

            return messageId;
        }

        // Update message content (for streaming)
        function updateMessage(messageId, content) {
            const messageElement = document.getElementById(messageId);
            if (messageElement) {
                const textElement = messageElement.querySelector('.message-text');
                if (textElement) {
                    // Clean up the content - remove special characters
                    const cleanContent = content
                        .replace(/[|*#]+/g, '') // Remove special markdown characters
                        .replace(/\s+/g, ' ') // Normalize whitespace
                        .trim();
                    textElement.textContent = cleanContent;
                }
            }
        }

        // Add source links to message
        function addSourceLinks(messageId, sources) {
            const messageElement = document.getElementById(messageId);
            if (messageElement && sources.length > 0) {
                const messageContent = messageElement.querySelector('.message-content');

                const sourcesDiv = document.createElement('div');
                sourcesDiv.className = 'source-links';

                const title = document.createElement('h4');
                title.textContent = 'Források:';
                sourcesDiv.appendChild(title);

                sources.slice(0, 5).forEach(source => {
                    const link = document.createElement('a');
                    link.href = source.url;
                    link.target = '_blank';
                    link.className = 'source-link';
                    link.textContent = source.title;
                    sourcesDiv.appendChild(link);
                });

                messageContent.appendChild(sourcesDiv);
            }
        }

        // Add typing indicator
        function addTypingIndicator() {
            const messagesContainer = document.getElementById('messagesContainer');
            const typingId = 'typing_' + Date.now();

            const typingDiv = document.createElement('div');
            typingDiv.className = 'message ai';
            typingDiv.id = typingId;

            typingDiv.innerHTML = `
                <div class="message-avatar">🤖</div>
                <div class="message-content">
                    <div class="typing-indicator">
                        <div class="typing-dot"></div>
                        <div class="typing-dot"></div>
                        <div class="typing-dot"></div>
                    </div>
                </div>
            `;

            messagesContainer.appendChild(typingDiv);
            messagesContainer.scrollTop = messagesContainer.scrollHeight;

            return typingId;
        }

        // Remove typing indicator
        function removeTypingIndicator(typingId) {
            const typingElement = document.getElementById(typingId);
            if (typingElement) {
                typingElement.remove();
            }
        }

        // Modal functions
