        .user .message-content {
            background: #007aff;
            color: white;
            border-bottom-right-radius: 8px;
        }

        .ai .message-content {
            background: #1c1c1e;
            border: 1px solid #38383a;
            color: #ffffff;
            border-bottom-left-radius: 8px;
        }

        .message-content h4 {
            color: #8e8e93;
            font-size: 0.9em;
